import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadInter = makeLoadFont('Inter');

const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: interFamily } = loadInter();



export type FormulaELowerThirdProps = Record<string, any>;

const FormulaELowerThird: React.FC<FormulaELowerThirdProps> = ({
  backgroundColor = "#e8e8e8",
  transparentBackground = true,
  durationInSeconds = 6,
  name = "MALLOY STUDIO",
  role = "TEAM PRINCIPAL",
  primaryColor = "#5dfc42", // Neon Green
  secondaryColor = "#150be8", // Royal Blue
  accentColor = "#111111", // Black
  textColorPrimary = "#111111", // Black on Green
  textColorSecondary = "#ffffff", // White on Blue
  position = "left",
  overallScale = 1,
  nameFontSize = 130,
  roleFontSize = 36,
  chevronStripLength = 40,
  checkerOffsetX = 0,
  chevronVelocity = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationFrames = Math.round(durationInSeconds * fps);
  const outroDuration = 30;
  const isOutro = frame >= durationFrames - outroDuration;
  const isLeft = position === "left";

  const slideDir = isLeft ? -1 : 1;
  const alignFlex = isLeft ? "flex-start" : "flex-end";
  const textAlign = isLeft ? "left" : "right";

  // Animation Springs
  const getSpring = (delay: number) => {
    const inSpring = spring({
      frame: frame - delay,
      fps,
      config: { damping: 14, stiffness: 120, mass: 0.8 },
    });

    const outSpring = spring({
      frame: frame - (durationFrames - outroDuration) - delay * 0.5,
      fps,
      config: { damping: 16, stiffness: 140 },
    });

    return isOutro ? 1 - outSpring : inSpring;
  };

  const roleAnim = getSpring(0);
  const nameAnim = getSpring(5);
  const chevronAnim = getSpring(10);
  const checkerAnim = getSpring(12);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Dynamic values based on animation
  const roleSlide = interpolate(roleAnim, [0, 1], [50 * slideDir, 0]);
  const nameSlide = interpolate(nameAnim, [0, 1], [80 * slideDir, 0]);
  const chevronSlide = interpolate(chevronAnim, [0, 1], [100 * slideDir, 0]);
  const checkerScale = interpolate(checkerAnim, [0, 1], [0, 1]);

  // Texture Movement (Chevron)
  const chevronSpeed = 3 * chevronVelocity;
  const chevronWidth = 30;
  const rawChevronOffset = (frame * chevronSpeed) % chevronWidth;
  const chevronOffset = isLeft ? rawChevronOffset : -rawChevronOffset;

  // Rough edge clip-paths simulating torn paper/tape
  const roughTopClipPath = "polygon(1% 5%, 8% 0%, 18% 4%, 30% 1%, 45% 5%, 60% 0%, 75% 4%, 88% 1%, 98% 5%, 100% 100%, 0% 100%)";
  const roughTopClipPathAlt = "polygon(2% 2%, 12% 6%, 25% 0%, 40% 5%, 55% 1%, 70% 6%, 85% 0%, 96% 4%, 100% 100%, 0% 100%)";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Background Tech Grid (Only visible if not transparent) */}
      {!transparentBackground && (
        <div style={{ position: "absolute", width: "100%", height: "100%", opacity: 0.05, backgroundImage: "linear-gradient(#000 1px, transparent 1px), linear-gradient(90deg, #000 1px, transparent 1px)", backgroundSize: "40px 40px" }} />
      )}

      {/* Main Container */}
      <div
        style={{
          position: "absolute",
          bottom: "12%",
          left: isLeft ? "5%" : "auto",
          right: !isLeft ? "5%" : "auto",
          display: "flex",
          flexDirection: "column",
          alignItems: alignFlex,
          width: "80%",
          maxWidth: "1400px",
          transform: `scale(${overallScale}) skewX(-6deg)`, 
          transformOrigin: isLeft ? "bottom left" : "bottom right",
        }}
      >
        
        {/* Checkered Flag Accent */}
        <div
          style={{
            position: "absolute",
            top: -20,
            left: isLeft ? -40 : "auto",
            right: !isLeft ? -40 : "auto",
            width: "80px",
            height: "80px",
            transform: `translateX(${checkerOffsetX}px) scale(${checkerScale})`,
            zIndex: 10,
            transformOrigin: isLeft ? "top right" : "top left",
            opacity: checkerAnim,
          }}
        >
          <svg width="100%" height="100%">
            <defs>
              <pattern id="checker" width="40" height="40" patternUnits="userSpaceOnUse">
                <rect width="20" height="20" fill={accentColor} />
                <rect x="20" y="20" width="20" height="20" fill={accentColor} />
                <rect x="20" y="0" width="20" height="20" fill="#ffffff" />
                <rect x="0" y="20" width="20" height="20" fill="#ffffff" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#checker)" />
          </svg>
        </div>

        {/* ROLE BOX */}
        <div
          style={{
            backgroundColor: secondaryColor,
            padding: "16px 40px",
            clipPath: roughTopClipPath,
            transform: `translateX(${roleSlide}px)`,
            opacity: roleAnim,
            marginBottom: "-15px", // Overlap with Name Box
            zIndex: 1,
            boxShadow: "0px 10px 30px rgba(0,0,0,0.5)",
          }}
        >
          <h2
            style={{
              fontFamily: interFamily,
              fontWeight: 900,
              fontSize: `${roleFontSize}px`,
              color: textColorSecondary,
              margin: 0,
              letterSpacing: "4px",
              textAlign,
              textTransform: "uppercase",
              transform: "skewX(6deg)", // Unskew text slightly for readability
            }}
          >
            {role}
          </h2>
        </div>

        {/* NAME BOX */}
        <div
          style={{
            backgroundColor: primaryColor,
            padding: "20px 50px",
            clipPath: roughTopClipPathAlt,
            transform: `translateX(${nameSlide}px)`,
            opacity: nameAnim,
            zIndex: 2,
            boxShadow: "0px 15px 40px rgba(0,0,0,0.4)",
          }}
        >
          <h1
            style={{
              fontFamily: antonFamily,
              fontSize: `${nameFontSize}px`,
              lineHeight: 0.9,
              color: textColorPrimary,
              margin: 0,
              textAlign,
              textTransform: "uppercase",
              transform: "skewX(4deg)", // Slight unskew to keep it aggressive but legible
            }}
          >
            {name}
          </h1>
        </div>

        {/* CHEVRON STRIP (MOVING TEXTURE) */}
        <div
          style={{
            backgroundColor: accentColor,
            width: `${chevronStripLength}%`,
            height: "35px",
            transform: `translateX(${chevronSlide}px)`,
            opacity: chevronAnim,
            zIndex: 3,
            marginTop: "-5px",
            position: "relative",
            overflow: "hidden",
            alignSelf: isLeft ? "flex-start" : "flex-end",
            marginLeft: isLeft ? "10%" : "0",
            marginRight: !isLeft ? "10%" : "0",
          }}
        >
          <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0 }}>
            <defs>
              <pattern
                id="chevrons"
                width={chevronWidth}
                height="35"
                patternUnits="userSpaceOnUse"
                patternTransform={`translate(${chevronOffset}, 0)`}
              >
                <path
                  d={
                    isLeft
                      ? "M0 0 L15 17.5 L0 35 L8 35 L23 17.5 L8 0 Z"
                      : "M30 0 L15 17.5 L30 35 L22 35 L7 17.5 L22 0 Z"
                  }
                  fill="rgba(255, 255, 255, 0.7)"
                />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#chevrons)" />
          </svg>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default FormulaELowerThird;